using Azure.Identity;
using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Specialized;

var blobClient = new BlobClient(
  new Uri("https://stdemostorage.blob.core.windows.net/uploads/photo.jpg"),
  new DefaultAzureCredential());

var sasBuilder = new BlobSasBuilder
{
  BlobContainerName = "uploads",
  BlobName = "photo.jpg",
  Resource = "b",
  StartsOn = DateTimeOffset.UtcNow.AddMinutes(-5),
  ExpiresOn = DateTimeOffset.UtcNow.AddHours(1)
};
sasBuilder.SetPermissions(BlobSasPermissions.Read);

var userDelegationKey = await blobClient.GetUserDelegationKeyAsync(
  sasBuilder.StartsOn.Value, sasBuilder.ExpiresOn.Value);
var sasToken = sasBuilder.ToSasQueryParameters(userDelegationKey, blobClient.AccountName);

Console.WriteLine($"https://stdemostorage.blob.core.windows.net/uploads/photo.jpg?{sasToken}");
